_service.sdl:
schema @link(url: "https://specs.apollo.dev/federation/v2.11", import: ["@external", "@key", "@shareable"]) {
  query: Query
  mutation: Mutation
  subscription: Subscription
}

"""Date with time (isoformat)"""
scalar DateTime

type Mutation {
  createOrder(portfolioId: ID!, contractSymbol: String!, side: String!, quantity: Int!, orderType: String!, limitPrice: Float = null): Order!
  cancelOrder(orderId: ID!): Boolean!
  createPortfolio(userId: String!, name: String!, initialCash: Float!): Portfolio!
}

extend type Option @key(fields: "id") {
  id: ID! @external
}

type Order {
  id: ID!
  portfolioId: ID!
  contractSymbol: String!
  side: String!
  quantity: Int!
  orderType: String!
  status: String!
  limitPrice: Float
  createdAt: DateTime!
  updatedAt: DateTime!
}

type Portfolio @key(fields: "id") @shareable {
  id: ID!
  userId: String! @shareable
  cashBalance: Float! @shareable
  positions: [Position!]!
}

type Position {
  id: ID!
  contractSymbol: String!
  quantity: Int!
  entryPrice: Float!
  option: Option!
}

type Query {
  _entities(representations: [_Any!]!): [_Entity]!
  _service: _Service!
  portfolio(userId: String!): Portfolio
}

type Subscription {
  portfolioUpdates(portfolioId: ID!): Portfolio!
}

scalar _Any

union _Entity = Option | Portfolio

type _Service {
  sdl: String!
}
